package bookstore

// groupCosts holds the price in cents of a group of k distinct books,
// indexed by group size 1..5.
var groupCosts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the total price in cents for the given basket of books,
// giving as big a discount as possible.
func Cost(books []int) int {
	// Count copies of each of the five titles.
	var counts [6]int
	for _, book := range books {
		counts[book-1]++
	}
	// Sort the counts in descending order (only five elements).
	for i := 0; i < 4; i++ {
		for j := i + 1; j < 5; j++ {
			if counts[j] > counts[i] {
				counts[i], counts[j] = counts[j], counts[i]
			}
		}
	}
	// Decompose the basket into groups. In round r, one copy is taken from
	// every title that still has copies, so the number of groups of size k
	// equals the drop in the sorted counts between position k-1 and k.
	var groups [6]int
	for k := 1; k <= 5; k++ {
		groups[k] = counts[k-1] - counts[k]
	}
	// A group of five plus a group of three costs 3000 + 2160 = 5160, while
	// two groups of four cost 2 * 2560 = 5120, so always prefer the latter.
	for pairs := 0; pairs < groups[5] && pairs < groups[3]; pairs++ {
		groups[5]--
		groups[3]--
		groups[4] += 2
	}
	total := 0
	for k := 1; k <= 5; k++ {
		total += groups[k] * groupCosts[k]
	}
	return total
}

